export const envelope = [27, 40, 27];

export default function build(api) {
  const [W, H, D] = api.size;

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Organic spine/lean of the elder mushroom
  function getStemCenter(y) {
    const cx = 13.0 + 1.2 * Math.sin(y * 0.12);
    const cz = 13.0 + 0.9 * Math.cos(y * 0.15) - 0.9;
    return [cx, cz];
  }

  // Stem radius profile
  function getStemRadius(y) {
    if (y <= 3) return 4.4 - y * 0.35;
    if (y <= 12) return 3.35 - (y - 3) * 0.09;
    if (y <= 21) return 2.54 + (y - 12) * 0.07;
    if (y <= 26) return 3.17 + (y - 21) * 0.5;
    return 5.67 + (y - 26) * 1.5;
  }

  // Cap dome radius profile
  function getCapRadius(y) {
    if (y < 26) return 0;
    if (y === 26) return 6.2;
    if (y === 27) return 8.6;
    if (y === 28) return 10.6;
    if (y === 29) return 11.6; // outer rim
    if (y === 30) return 11.4;
    if (y === 31) return 11.0;
    if (y === 32) return 10.2;
    if (y === 33) return 9.2;
    if (y === 34) return 7.9;
    if (y === 35) return 6.4;
    if (y === 36) return 4.7;
    if (y === 37) return 2.9;
    if (y === 38) return 1.4;
    return 0;
  }

  // 1. Build the Warped Towering Stem & Conforming Base
  for (let y = 0; y <= 26; y++) {
    const [cx, cz] = getStemCenter(y);
    const r = getStemRadius(y);
    const minX = Math.floor(cx - r - 1);
    const maxX = Math.ceil(cx + r + 1);
    const minZ = Math.floor(cz - r - 1);
    const maxZ = Math.ceil(cz + r + 1);

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const d = Math.hypot(x - cx, z - cz);
        if (d <= r) {
          let block;
          if (d >= r - 1.1) {
            // Outer skin with vertical bioluminescent streaks
            const angle = Math.atan2(z - cz, x - cx);
            const vein = Math.sin(angle * 3.0 + y * 0.35);
            if (vein > 0.82) {
              block = "minecraft:shroomlight";
            } else if (vein < -0.85) {
              block = "minecraft:ochre_froglight";
            } else if ((x + z + y) % 3 === 0) {
              block = "minecraft:warped_hyphae";
            } else if ((x + z) % 2 === 0) {
              block = "minecraft:warped_stem[axis=y]";
            } else {
              block = "minecraft:stripped_warped_stem[axis=y]";
            }
          } else {
            block = "minecraft:mushroom_stem";
          }

          setBlock(x, y, z, block);

          // Follow the ground downwards on the base course
          if (y === 0) {
            const gh = api.heightAt(x, z);
            if (gh < 0) {
              for (let gy = gh; gy < 0; gy++) {
                setBlock(x, gy, z, "minecraft:stripped_warped_stem[axis=y]");
              }
            } else if (gh > 0) {
              for (let gy = 0; gy <= gh; gy++) {
                setBlock(x, gy, z, "minecraft:stripped_warped_stem[axis=y]");
              }
            }
          }
        }
      }
    }
  }

  // 2. Flaring Root Buttresses adhering to terrain slopes
  const rootAngles = [0.35, 1.55, 2.75, 4.05, 5.25];
  for (const angle of rootAngles) {
    for (let d = 2.5; d <= 8.2; d += 0.5) {
      const rx = Math.round(13.0 + d * Math.cos(angle));
      const rz = Math.round(13.0 + d * Math.sin(angle));
      const rootH = Math.round(5.5 * (1.0 - (d - 2.5) / 6.0));
      const gh = api.heightAt(rx, rz);
      const minY = Math.min(0, gh);
      const maxY = Math.max(gh, rootH);

      for (let y = minY; y <= maxY; y++) {
        const isTop = y === maxY;
        let b = isTop ? "minecraft:warped_hyphae" : "minecraft:stripped_warped_stem[axis=y]";
        if (isTop && (rx + rz) % 4 === 0) b = "minecraft:moss_block";
        if (isTop && d > 6 && (rx * 3 + rz) % 5 === 0) b = "minecraft:shroomlight";
        setBlock(rx, y, rz, b);
      }

      // Root lateral thickness
      if (d < 5.5) {
        for (const s of [-1, 1]) {
          const px = Math.round(rx + s * -Math.sin(angle) * 0.8);
          const pz = Math.round(rz + s * Math.cos(angle) * 0.8);
          const pgh = api.heightAt(px, pz);
          const pMinY = Math.min(0, pgh);
          const pMaxY = Math.max(pgh, rootH - 1);
          for (let py = pMinY; py <= pMaxY; py++) {
            setBlock(px, py, pz, "minecraft:stripped_warped_stem[axis=y]");
          }
        }
      }
    }
  }

  // 3. Colossal Bioluminescent Cap (Underside Gills & Upper Dome)
  for (let y = 26; y <= 38; y++) {
    const [cx, cz] = getStemCenter(y);
    const rOuter = getCapRadius(y);
    const rInner = y <= 28 ? 0 : Math.max(0, rOuter - 2.0);

    const minX = Math.floor(cx - rOuter - 1);
    const maxX = Math.ceil(cx + rOuter + 1);
    const minZ = Math.floor(cz - rOuter - 1);
    const maxZ = Math.ceil(cz + rOuter + 1);

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const d = Math.hypot(x - cx, z - cz);
        if (d <= rOuter) {
          if (y <= 29) {
            // Underside gills radiating from stalk
            const angle = Math.atan2(z - cz, x - cx);
            const gillWave = Math.sin(angle * 18.0);
            if (d >= rOuter - 0.9) {
              setBlock(x, y, z, "minecraft:warped_wart_block");
            } else if (y === 26 || y === 27) {
              if (gillWave > 0.3) {
                setBlock(x, y, z, "minecraft:mushroom_stem");
              } else if (gillWave < -0.7) {
                setBlock(x, y, z, "minecraft:shroomlight");
              } else {
                setBlock(x, y, z, "minecraft:stripped_warped_stem[axis=y]");
              }
            } else {
              if (gillWave > 0.4) {
                setBlock(x, y, z, "minecraft:mushroom_stem");
              } else if (gillWave < -0.6) {
                setBlock(x, y, z, "minecraft:ochre_froglight");
              } else {
                setBlock(x, y, z, "minecraft:warped_hyphae");
              }
            }
          } else {
            // Upper dome outer skin & inner flesh
            if (d < rInner && y < 36) {
              setBlock(x, y, z, "minecraft:mushroom_stem");
            } else {
              const spotNoise =
                Math.sin(x * 1.3 + y * 0.7) * Math.cos(z * 1.3 - y * 0.5) +
                Math.sin(x * 0.8 - z * 0.9);
              let block = "minecraft:warped_wart_block";
              if (spotNoise > 0.72) {
                block = "minecraft:shroomlight";
              } else if (spotNoise > 0.45) {
                block = "minecraft:ochre_froglight";
              } else if (spotNoise < -0.65) {
                block = "minecraft:dark_prismarine";
              } else if ((x + z + y) % 7 === 0) {
                block = "minecraft:prismarine_bricks";
              }
              setBlock(x, y, z, block);
            }
          }
        }
      }
    }
  }

  // 4. Hollow Sanctuary Loft inside Upper Stem (y = 24 to 27)
  // Floor course at y = 23
  for (let ix = 11; ix <= 15; ix++) {
    for (let iz = 10; iz <= 14; iz++) {
      setBlock(ix, 23, iz, api.theme.wood.planks);
    }
  }

  // Air volume for compiler interior fit-out
  for (let iy = 24; iy <= 27; iy++) {
    for (let ix = 11; ix <= 15; ix++) {
      for (let iz = 10; iz <= 14; iz++) {
        setBlock(ix, iy, iz, "minecraft:air");
      }
    }
  }

  // Ceiling cap at y = 28
  for (let ix = 11; ix <= 15; ix++) {
    for (let iz = 10; iz <= 14; iz++) {
      setBlock(ix, 28, iz, "minecraft:warped_hyphae");
    }
  }

  // Sanctuary doorway & lookout windows
  setBlock(13, 24, 10, "minecraft:air");
  setBlock(13, 25, 10, "minecraft:air");
  setBlock(13, 24, 9, "minecraft:air");
  setBlock(13, 25, 9, "minecraft:air");
  setBlock(13, 23, 9, api.theme.wood.planks);

  setBlock(11, 25, 12, api.theme.wood.fence); // West window
  setBlock(15, 25, 12, api.theme.wood.fence); // East window
  setBlock(13, 25, 14, api.theme.wood.fence); // South window

  // 5. Spiral Shelf Fungal Walkways wrapping the stalk
  const totalSteps = 58;
  for (let step = 0; step <= totalSteps; step++) {
    const t = step / totalSteps;
    const y = Math.round(1 + t * 23);
    const angle = -0.6 + t * 3.7 * Math.PI;
    const [scx, scz] = getStemCenter(y);
    const sr = getStemRadius(y);
    const wr = sr + 1.3;

    const wx = Math.round(scx + wr * Math.cos(angle));
    const wz = Math.round(scz + wr * Math.sin(angle));

    // Platform treads & shelf brackets
    for (let rad = sr - 0.5; rad <= wr + 0.6; rad += 0.6) {
      const bx = Math.round(scx + rad * Math.cos(angle));
      const bz = Math.round(scz + rad * Math.sin(angle));

      setBlock(bx, y - 1, bz, "minecraft:brown_mushroom_block");
      setBlock(bx, y, bz, api.theme.wood.planks);
      setBlock(bx, y + 1, bz, "minecraft:air");
      setBlock(bx, y + 2, bz, "minecraft:air");
    }

    // Outer protective fence
    const rx = Math.round(scx + (wr + 0.8) * Math.cos(angle));
    const rz = Math.round(scz + (wr + 0.8) * Math.sin(angle));
    setBlock(rx, y, rz, api.theme.wood.planks);
    setBlock(rx, y + 1, rz, api.theme.wood.fence);

    // Ground connection steps at base of path
    if (step <= 2) {
      const gh = api.heightAt(wx, wz);
      for (let sy = Math.min(0, gh); sy <= y; sy++) {
        setBlock(wx, sy, wz, api.theme.wood.planks);
      }
    }

    // Glowing soul lanterns on fence posts
    if (step % 12 === 6) {
      setBlock(rx, y + 2, rz, api.theme.wood.fence);
      setBlock(rx, y + 3, rz, "minecraft:soul_lantern[hanging=false]");
    }
  }

  // 6. Rest Balcony (y = 12) & Sanctuary Lookout Balcony (y = 23-24)
  // Mid lookout at y = 12
  const [mcx, mcz] = getStemCenter(12);
  const msr = getStemRadius(12);
  for (let ba = 2.0; ba <= 3.2; ba += 0.15) {
    for (let brad = msr; brad <= msr + 3.0; brad += 0.6) {
      const bx = Math.round(mcx + brad * Math.cos(ba));
      const bz = Math.round(mcz + brad * Math.sin(ba));
      setBlock(bx, 11, bz, "minecraft:brown_mushroom_block");
      setBlock(bx, 12, bz, api.theme.wood.planks);
      setBlock(bx, 13, bz, "minecraft:air");
      setBlock(bx, 14, bz, "minecraft:air");
      if (brad >= msr + 2.4) {
        setBlock(bx, 13, bz, api.theme.wood.fence);
      }
    }
  }

  // Top landing balcony outside sanctuary doorway
  const [tcx, tcz] = getStemCenter(23);
  const tsr = getStemRadius(23);
  for (let ba = 4.4; ba <= 5.6; ba += 0.15) {
    for (let brad = tsr; brad <= tsr + 3.2; brad += 0.6) {
      const bx = Math.round(tcx + brad * Math.cos(ba));
      const bz = Math.round(tcz + brad * Math.sin(ba));
      setBlock(bx, 22, bz, "minecraft:brown_mushroom_block");
      setBlock(bx, 23, bz, api.theme.wood.planks);
      setBlock(bx, 24, bz, "minecraft:air");
      setBlock(bx, 25, bz, "minecraft:air");
      if (brad >= tsr + 2.5) {
        setBlock(bx, 24, bz, api.theme.wood.fence);
      }
      if (ba > 4.9 && ba < 5.1 && brad >= tsr + 2.5) {
        setBlock(bx, 25, bz, api.theme.wood.fence);
        setBlock(bx, 26, bz, "minecraft:soul_lantern[hanging=false]");
      }
    }
  }

  // 7. Hanging Spore Tendrils & Bioluminescent Drops
  const tendrilSeeds = [
    { angle: 0.25, rad: 8.0, len: 6 },
    { angle: 0.65, rad: 10.2, len: 4 },
    { angle: 1.1, rad: 7.5, len: 7 },
    { angle: 1.55, rad: 9.8, len: 5 },
    { angle: 2.0, rad: 8.2, len: 8 },
    { angle: 2.45, rad: 10.5, len: 4 },
    { angle: 2.9, rad: 7.2, len: 6 },
    { angle: 3.35, rad: 9.5, len: 5 },
    { angle: 3.8, rad: 8.0, len: 7 },
    { angle: 4.25, rad: 10.2, len: 4 },
    { angle: 4.7, rad: 7.8, len: 8 },
    { angle: 5.15, rad: 9.8, len: 5 },
    { angle: 5.6, rad: 8.4, len: 6 },
    { angle: 6.0, rad: 10.4, len: 4 },
  ];

  for (const t of tendrilSeeds) {
    const [ccx, ccz] = getStemCenter(28);
    const tx = Math.round(ccx + t.rad * Math.cos(t.angle));
    const tz = Math.round(ccz + t.rad * Math.sin(t.angle));
    if (tx < 1 || tx > 25 || tz < 1 || tz > 25) continue;

    let yStart = -1;
    for (let y = 26; y <= 31; y++) {
      const d = Math.hypot(tx - getStemCenter(y)[0], tz - getStemCenter(y)[1]);
      if (d <= getCapRadius(y)) {
        yStart = y;
        break;
      }
    }

    if (yStart > 0) {
      for (let k = 1; k <= t.len; k++) {
        const yCur = yStart - k;
        if (yCur < 16) break;
        if (k === t.len) {
          if (t.len >= 6) {
            setBlock(tx, yCur, tz, "minecraft:spore_blossom");
          } else {
            setBlock(tx, yCur, tz, "minecraft:soul_lantern[hanging=true]");
          }
        } else if (k === t.len - 1) {
          setBlock(tx, yCur, tz, "minecraft:shroomlight");
        } else if (k % 2 === 0) {
          setBlock(tx, yCur, tz, "minecraft:weeping_vines[age=25]");
        } else {
          setBlock(tx, yCur, tz, "minecraft:chain[axis=y]");
        }
      }
    }
  }

  return {
    name: "Elder Glowcap",
    seatY: 0,
    anchors: {
      front: [13, 0, 0],
      door: [13, 24, 10],
      base_path: [15, 1, 10],
    },
    interiors: [
      {
        min: [11, 24, 10],
        max: [15, 27, 14],
        kind: "loft",
      },
    ],
  };
}
